97: function tone(freq, type, dur, vol, t) {
98:   if (!ACtx) return;
99:   const o = ACtx.createOscillator(), g = ACtx.createGain();
100:   o.type = type; o.frequency.setValueAtTime(freq, t);
101:   g.gain.setValueAtTime(vol || 0.08, t); g.gain.exponentialRampToValueAtTime(0.001, t + dur);
102:   o.connect(g); g.connect(ACtx.destination);
103:   o.start(t); o.stop(t + dur);
104: }
105: function noiseBurst(dur, vol, t) {
106:   if (!ACtx) return;
107:   const len = ACtx.sampleRate * dur, buf = ACtx.createBuffer(1, len, ACtx.sampleRate);
108:   const d = buf.getChannelData(0);
