110:   const n = ACtx.createBufferSource(), g = ACtx.createGain();
111:   n.buffer = buf;
112:   g.gain.setValueAtTime(vol || 0.06, t); g.gain.exponentialRampToValueAtTime(0.001, t + dur);
113:   n.connect(g); g.connect(ACtx.destination);
114:   n.start(t); n.stop(t + dur);
115: }
