217: function hash2(n) {
218:   n = (n >>> 0) ^ ((n >>> 0) << 13);
219:   let h = (n >>> 0) ^ ((n >>> 0) >>> 17);
220:   return (h >>> 0) ^ ((h >>> 0) << 5);
