233: /* ============================ WORLD / CHUNKS ============================ */
234: function makeGround(cx, cy) {
235:   const size = CHUNK;
236:   const geo = new THREE.PlaneGeometry(size, size, 56, 56);
237:   geo.rotateX(-Math.PI / 2);
238:   const colors = [];
239:   const pos = geo.attributes.position;
240:   const centerX = (cx * CHUNK_CELLS + CHUNK_CELLS / 2) * CELL;
241:   const centerZ = (cy * CHUNK_CELLS + CHUNK_CELLS / 2) * CELL;
242:   for (let i = 0; i < pos.count; i++) {
243:     const wx = centerX + pos.getX(i);
244:     const wz = centerZ - pos.getY(i); // local Y of the plane maps to world -Z after rotation
245:     const lcx = ((wx % CELL) + CELL) % CELL, lcz = ((wz % CELL) + CELL) % CELL;
246:     const road = lcx < ROAD / 2 || lcx > CELL - ROAD / 2 || lcz < ROAD / 2 || lcz > CELL - ROAD / 2;
247:     let r, g, b;
248:     if (road) { r = 0.22; g = 0.23; b = 0.25; }
249:     else {
250:       const base = 0.46 + rand2(cx, cy, 1) * 0.14;
251:       r = base + (Math.random() - 0.5) * 0.04; g = base + 0.02; b = base + 0.06;
252:     }
253:     colors.push(r, g, b);
254:   }
255:   geo.setAttribute('color', new THREE.Float32BufferAttribute(colors, 3));
256:   const mesh = new THREE.Mesh(geo, matGround);
257:   mesh.position.set(centerX, 0, centerZ);
258:   scene.add(mesh);
259:   staticMeshes.push(mesh);
260:   return mesh;
261: }
