263: function makeBuilding(cx, cy, bx, by) {
264:   const h = hash2(bx * 997 + by * 1013 + cx * 131 + cy * 137);
265:   if ((h >>> 0) / 0xffffffff > 0.72) return null;
266:   const h2 = hash2(bx * 31 + by * 71 + cx * 17 + cy * 19);
267:   const h3 = hash2(bx * 131 + by * 97 + cx * 23 + cy * 29);
268:   const w = 7 + (h2 >>> 0) % 10;
269:   const d = 7 + (h3 >>> 0) % 10;
270:   const stories = 3 + ((hash2(bx * 53 + by * 61 + cx * 5 + cy * 7) >>> 0) % 7);
271:   const bh = stories * 3.1;
272:   const lotOx = bx * CELL + ROAD / 2 + 1.5;
273:   const lotOz = by * CELL + ROAD / 2 + 1.5;
274:   const px = lotOx + 1.5 + ((hash2(bx * 11 + by * 13 + cx * 3 + cy * 3) >>> 0) % Math.max(1, LOT - w - 3));
275:   const pz = lotOz + 1.5 + ((hash2(bx * 7 + by * 5 + cx * 9 + cy * 11) >>> 0) % Math.max(1, LOT - d - 3));
276:   const gx = px; // px is already absolute world x
277:   const gz = pz; // pz is already absolute world z
278:   const gray = 0.55 + ((hash2(bx * 3 + by * 3 + cx * 7 + cy * 11) >>> 0) / 0xffffffff) * 0.22;
279:   const g = Math.floor(gray * 255);
280:   const mat = new THREE.MeshLambertMaterial({ color: (g << 16) | (g << 8) | g, map: texFacade });
281:   mat.map.repeat.set(w / 3, bh / 3);
282:   const mesh = new THREE.Mesh(new THREE.BoxGeometry(w, bh, d), mat);
283:   mesh.position.set(gx, bh / 2, gz);
284:   scene.add(mesh);
285:   staticMeshes.push(mesh);
286:   const b = {
287:     min: new THREE.Vector3(gx - w / 2, 0, gz - d / 2),
288:     max: new THREE.Vector3(gx + w / 2, bh, gz + d / 2),
289:     _chunk: null
290:   };
291:   return { mesh, mat, box: b };
292: }
