294: function createChunk(cx, cy) {
295:   if (chunks.has(`${cx},${cy}`)) return chunks.get(`${cx},${cy}`);
296:   const chunk = { cx, cy, ground: null, buildings: [], created: now() };
297:   chunk.ground = makeGround(cx, cy);
298:   for (let bx = cx * CHUNK_CELLS; bx < (cx + 1) * CHUNK_CELLS; bx++) {
299:     for (let by = cy * CHUNK_CELLS; by < (cy + 1) * CHUNK_CELLS; by++) {
300:       const res = makeBuilding(cx, cy, bx, by);
301:       if (res) { res.box._chunk = chunk; chunk.buildings.push(res); buildings.push(res.box); }
302:     }
303:   }
304:   chunks.set(`${cx},${cy}`, chunk);
305:   return chunk;
306: }
