308: function disposeChunk(chunk) {
309:   scene.remove(chunk.ground);
310:   const gi = staticMeshes.indexOf(chunk.ground); if (gi >= 0) staticMeshes.splice(gi, 1);
311:   chunk.ground.geometry.dispose();
312:   for (const b of chunk.buildings) {
313:     scene.remove(b.mesh);
314:     const si = staticMeshes.indexOf(b.mesh); if (si >= 0) staticMeshes.splice(si, 1);
315:     b.mesh.geometry.dispose(); b.mesh.material.dispose();
316:     const bi = buildings.indexOf(b.box); if (bi >= 0) buildings.splice(bi, 1);
317:   }
318:   chunks.delete(`${chunk.cx},${chunk.cy}`);
319: }
