325:   for (let x = cx - 2; x <= cx + 2; x++) {
326:     for (let y = cy - 2; y <= cy + 2; y++) { keep.add(`${x},${y}`); createChunk(x, y); }
327:   }
328:   for (const [key, ch] of chunks) {
329:     if (!keep.has(key) && now() - ch.created > 1.5) disposeChunk(ch);
330:   }
331: }
